<div class="page-title"><div><em>CARD OPERATIONS</em><h1>Card management</h1><p>Issue, monitor and control customer cards.</p></div><button class="btn">+ Issue card</button></div><div class="stats four"><div><i>▤</i><span>Total cards<b><?=count($cards)?></b></span></div><div><i>✓</i><span>Active<b><?=count(array_filter($cards,fn($c)=>$c['status']==='active'))?></b></span></div><div><i>▣</i><span>Frozen<b><?=count(array_filter($cards,fn($c)=>$c['is_frozen']))?></b></span></div><div><i>!</i><span>Blocked<b><?=count(array_filter($cards,fn($c)=>$c['status']==='blocked'))?></b></span></div></div><section class="panel"><div class="data-table card-table"><div class="tr th"><span>Customer</span><span>Card</span><span>Account</span><span>Limit</span><span>Status</span></div><?php foreach($cards as $c):?><div class="tr"><span class="name"><i><?=initials($c['first_name'].' '.$c['last_name'])?></i><b><?=html_escape($c['first_name'].' '.$c['last_name'])?></b></span><span><?=html_escape($c['network'])?> •<?=$c['last_four']?></span><span>•<?=substr($c['account_number'],-4)?></span><strong><?=money($c['daily_limit'])?></strong><span class="<?=status_class($c['is_frozen']?'frozen':$c['status'])?>"><?=ucfirst($c['is_frozen']?'frozen':$c['status'])?></span></div><?php endforeach?></div></section>
